from itertools import product

def grs_min_weight(n: int, k: int, p: int) -> int:
    alpha = list(range(n))
    def ev(coeffs, x):
        acc = 0
        for c in reversed(coeffs):
            acc = (acc * x + c) % p
        return acc
    best = None
    for coeffs in product(range(p), repeat=k):
        if all(c == 0 for c in coeffs):
            continue
        w = sum(1 for a in alpha if ev(coeffs, a) != 0)
        best = w if best is None else min(best, w)
    return best

if __name__ == '__main__':
    n, k, p = 7, 3, 7
    print('min weight', grs_min_weight(n, k, p), 'bound', n - k + 1)

from itertools import product

def unique_decode_demo(n: int, k: int, p: int, f):
    alpha = list(range(n))
    def ev(coeffs, x):
        acc = 0
        for c in reversed(coeffs):
            acc = (acc * x + c) % p
        return acc
    code = [ev(f, a) for a in alpha]
    tau = (n - k) // 2
    recv = code[:]
    for i in range(tau):
        recv[i] = (recv[i] + 1) % p
    near = [
        [ev(c, a) for a in alpha]
        for c in product(range(p), repeat=k)
        if sum(1 for a, b in zip(recv, [ev(c, a) for a in alpha]) if a != b) <= tau
    ]
    return len(near), near == [code]

if __name__ == '__main__':
    print(unique_decode_demo(11, 3, 11, [2, 3, 1]))

from itertools import product

def bch_min_kernel_weight(n: int, t: int, p: int) -> int:
    alpha = list(range(1, n + 1))
    H = [[pow(a, j, p) for a in alpha] for j in range(t)]
    best = None
    for c in product(range(p), repeat=n):
        if all(x == 0 for x in c):
            continue
        if all(sum(H[j][i] * c[i] for i in range(n)) % p == 0 for j in range(t)):
            w = sum(1 for x in c if x != 0)
            best = w if best is None else min(best, w)
    return best

if __name__ == '__main__':
    print('min kernel weight', bch_min_kernel_weight(6, 2, 7), '> t = 2')

