function WeightCertificate(alpha[1..n], f, p):
    require f != 0 and deg(f) < k and alpha distinct
    z <- 0
    for i in 1..n:
        if HornerEval(f, alpha[i], p) == 0: z <- z + 1
    assert z <= deg(f)               # card_eval_zero_le_natDegree
    return (weight = n - z, bound = n - k + 1, ok = (n - z >= n - k + 1))

function ISDWork(n, k, t):
    require 0 <= t <= n - k
    p_succ <- C(n - k, t) / C(n, t)   # information set avoids all errors
    work   <- 1 / p_succ              # expected iterations
    return log2(work)

